ContractView013 = build_contract_view([{'api_id': 'API-IMG-008', 'app': 'imaging', 'domain': 'Imaging', 'api_name': 'Orthanc Study 재동기화', 'method': 'POST', 'endpoint': '/api/v1/imaging-studies/{study_id}/resync', 'django_path': 'api/v1/imaging-studies/<uuid:study_id>/resync', 'roles': ['SYSTEM_ADMIN'], 'permission': 'integration.retry', 'service_scope': None, 'request_contract': 'Path: study_id: UUID, 필수\nQuery: -\nBody: {\n  "reason": "동기화 누락 확인",\n  "force": false\n}', 'validation': 'SYSTEM_ADMIN + integration.retry\n• Study 및 orthanc_study_id 존재\n• reason 필수 5~500자\n• force=true는 SYSTEM_ADMIN만 허용\n• 동일 Study RESYNC 작업 중복 방지', 'related_db': 'ImagingStudy (imaging_imagingstudy),SeriesReference (imaging_seriesreference),IntegrationTransaction (interoperability_integrationtransaction),AuditLog (audit_auditlog),OutboxEvent (common_outboxevent)', 'processing': '• Study 행 select_for_update\n• Orthanc REST로 Study/Series 메타데이터 재조회\n• 환자·오더 재매칭 및 Series Upsert\n• 완전성·AI 적합성 재검증\n• IntegrationTransaction·AuditLog·OutboxEvent 저장\n상태: RECEIVING|INCOMPLETE|UNMATCHED|ERROR|AVAILABLE\n→ AVAILABLE|INCOMPLETE|UNMATCHED|ERROR\n• 재동기화 시 SeriesReference의 frame_count/rows/columns/is_complete Snapshot도 갱신\n• 원본 status=ARCHIVED는 삭제하지 않으며, 보관 Study가 재사용 대상이면 기존 정합성 검증 후 AVAILABLE 복원 가능', 'response_contract': '{\n  "study_id": "uuid",\n  "previous_status": "INCOMPLETE",\n  "status": "AVAILABLE",\n  "series_count": 3,\n  "instance_count": 246,\n  "last_synced_at": "ISO-8601"\n}', 'success': '200 OK', 'error_contract': 'AUTH_REQUIRED(401)\nPERMISSION_DENIED(403)\nIMAGING_STUDY_NOT_FOUND(404)\nORTHANC_REFERENCE_MISSING(409)\nSTUDY_RESYNC_ALREADY_RUNNING(409)\nORTHANC_UNAVAILABLE(503)', 'transaction': 'O(필수: 재동기화 요청+IntegrationTransaction+AuditLog+Outbox 원자화; Orthanc 호출은 Commit 후 Worker)', 'transactional': True, 'event': 'imaging.study.resynced.v1\n실패 시 imaging.study.resync_failed.v1\n알림: SYSTEM_ADMIN: 반복 동기화 실패 운영 알림', 'note': '권한유형: ADMIN_PERMISSION(integration.retry) / RADIOLOGY의 기술 재동기화 실행 권한 제거', 'primary_model': 'imaging.SeriesReference', 'audit_required': True}])
ContractView014 = build_contract_view([{'api_id': 'API-IMG-005', 'app': 'imaging', 'domain': 'Imaging', 'api_name': 'Study Series 목록 조회', 'method': 'GET', 'endpoint': '/api/v1/imaging-studies/{study_id}/series', 'django_path': 'api/v1/imaging-studies/<uuid:study_id>/series', 'roles': ['NEUROLOGIST', 'NEUROSURGEON', 'RADIOLOGY'], 'permission': None, 'service_scope': None, 'request_contract': 'Path: study_id: UUID, 필수\nQuery: modality: CT|MR, 선택\nai_eligible: true|false, 선택\ncomplete: true|false, 선택\nBody: -', 'validation': 'USER_ROLE + 환자/Encounter/Worklist Object Scope\n• Study 존재 여부\n• Query Enum/Boolean 검증', 'related_db': 'ImagingStudy (imaging_imagingstudy)\nSeriesReference (imaging_seriesreference)', 'processing': '• 해당 Study의 SeriesReference 조회\n• SeriesNumber 오름차순 정렬\n• AI 입력 적합성 및 제외 사유 포함\n• 조회 AuditLog 기록\n• instance_count/frame_count/rows/columns/is_complete는 Orthanc stable-study/resync 시 SeriesReference에 저장된 DB Snapshot을 사용', 'response_contract': '{\n  "study_id": "uuid",\n  "series": [\n    {\n      "series_id": "uuid",\n      "series_instance_uid": "1.2.840...",\n      "series_number": 2,\n      "modality": "CT",\n      "series_description": "BRAIN NON CONTRAST",\n      "instance_count": 82,\n      "slice_thickness": 5.0,\n      "is_complete": true,\n      "is_ai_eligible": true,\n      "ai_exclusion_reason": ""\n    }\n  ]\n}', 'success': '200 OK', 'error_contract': 'AUTH_REQUIRED(401)\nPERMISSION_DENIED(403)\nIMAGING_STUDY_NOT_FOUND(404)', 'transaction': 'X(업무 데이터 조회 전용; Audit/Integration 기록은 별도 로깅 트랜잭션)', 'transactional': False, 'event': '-', 'note': '권한유형: USER_ROLE + 환자/Encounter/Worklist 관계. SYSTEM_ADMIN은 임상본문·환자식별정보 접근 금지', 'primary_model': 'imaging.SeriesReference', 'audit_required': True}])
ContractView015 = build_contract_view([{'api_id': 'API-DICOM-002', 'app': 'imaging', 'domain': 'DICOM Viewer', 'api_name': '원본영상·AI Overlay·Final 판독 Viewer Context', 'method': 'GET', 'endpoint': '/api/v1/imaging-studies/{study_id}/viewer-context', 'django_path': 'api/v1/imaging-studies/<uuid:study_id>/viewer-context', 'roles': ['NEUROLOGIST', 'NEUROSURGEON', 'RADIOLOGY'], 'permission': None, 'service_scope': None, 'request_contract': 'Path: study_id; Query: include_ai_overlay(default true)', 'validation': '환자 담당/협진/판독 Worklist 관계; Study=AVAILABLE; Overlay는 COMPLETED Result + AVAILABLE AIResultArtifact만', 'related_db': 'ImagingStudy (imaging_imagingstudy),SeriesReference (imaging_seriesreference),AIAnalysis (ai_aianalysis),AIAnalysisResult (ai_aianalysisresult),AIResultArtifact (ai_airesultartifact),DicomObjectReference (imaging_dicomobjectreference),RadiologyReport (radiology_radiologyreport),AuditLog (audit_auditlog)', 'processing': '원본 Series, short-lived WADO URL, AI 정량값과 SEG/SR Overlay, is_current FINAL|AMENDED 판독을 결합. AI Result↔DICOM은 ai_airesultartifact.result_id+dicom_object_reference_id만 사용', 'response_contract': 'study,viewer_session,series[],ai{analysis_id,result,artifacts[{artifact_type,dicom_object_reference_id,retrieve_url}]},final_report|null; AI/의료진 값을 별도 객체로 반환', 'success': '200 OK', 'error_contract': '403 VIEWER_ACCESS_FORBIDDEN / 404 STUDY_NOT_FOUND / 409 STUDY_NOT_AVAILABLE', 'transaction': 'X(조회 전용; VIEW_STUDY Audit 별도 기록)', 'transactional': False, 'event': '-', 'note': '권한유형: USER_ROLE + Object Scope / DicomObjectReference 직접 AI FK 금지', 'primary_model': 'imaging.SeriesReference', 'audit_required': True}])
ContractView016 = build_contract_view([{'api_id': 'API-IMG-007', 'app': 'imaging', 'domain': 'Imaging', 'api_name': 'OHIF Viewer Session 발급', 'method': 'POST', 'endpoint': '/api/v1/imaging-studies/{study_id}/viewer-session', 'django_path': 'api/v1/imaging-studies/<uuid:study_id>/viewer-session', 'roles': ['NEUROLOGIST', 'NEUROSURGEON', 'RADIOLOGY'], 'permission': None, 'service_scope': None, 'request_contract': 'Path: study_id: UUID, 필수\nQuery: -\nBody: {\n  "purpose": "DIAGNOSIS|CONSULTATION|FOLLOW_UP",\n  "include_ai_overlay": true\n}', 'validation': 'USER_ROLE + 환자/Encounter/Worklist Object Scope\n• Study status=AVAILABLE\n• include_ai_overlay=true이면 COMPLETED 분석과 AVAILABLE SEG 존재\n• 목적값 Enum 검증', 'related_db': 'ImagingStudy (imaging_imagingstudy)\nDicomObjectReference (imaging_dicomobjectreference)\nAIResultArtifact (ai_airesultartifact)\nAuditLog (audit_auditlog)', 'processing': '• Study 접근권한 재검증\n• 5분 내외 단기 Viewer Token/서명 Session 생성\n• DICOMweb Base URL과 StudyInstanceUID 기반 OHIF Launch URL 구성\n• OPEN_OHIF_VIEWER AuditLog 기록\n• Django는 DICOM Pixel Data를 중계하지 않음', 'response_contract': '{\n  "launch_url": "/viewer?StudyInstanceUIDs=1.2.840...",\n  "dicomweb_base_url": "/dicom-web",\n  "viewer_token": "short-lived-token",\n  "expires_at": "ISO-8601",\n  "ai_overlay_available": true\n}', 'success': '201 Created', 'error_contract': 'AUTH_REQUIRED(401)\nVIEWER_ACCESS_FORBIDDEN(403)\nIMAGING_STUDY_NOT_FOUND(404)\nSTUDY_NOT_AVAILABLE(409)\nAI_OVERLAY_NOT_AVAILABLE(409)', 'transaction': 'X(Short-lived Viewer Token 발급; 업무 DB 상태 변경 없음)', 'transactional': False, 'event': '-', 'note': '권한유형: USER_ROLE + 환자/Encounter/Worklist 관계. SYSTEM_ADMIN은 임상본문·환자식별정보 접근 금지', 'primary_model': 'imaging.ImagingStudy', 'audit_required': True}])
ContractView017 = build_contract_view([{'api_id': 'API-DICOM-001', 'app': 'imaging', 'domain': 'DICOMweb', 'api_name': 'OHIF DICOM Study/Series QIDO 조회', 'method': 'GET', 'endpoint': '/dicom-web/studies/{study_instance_uid}/series', 'django_path': 'dicom-web/studies/<str:study_instance_uid>/series', 'roles': [], 'permission': None, 'service_scope': 'dicomweb.read', 'request_contract': 'Path: study_instance_uid; Header: Accept=application/dicom+json; Query: SeriesInstanceUID,Modality,offset,limit', 'validation': 'Viewer Token의 study_id/StudyInstanceUID binding·만료·dicomweb.read Scope; Study=AVAILABLE; Token 외 Study 접근 금지', 'related_db': 'ImagingStudy (imaging_imagingstudy),SeriesReference (imaging_seriesreference),DicomObjectReference (imaging_dicomobjectreference),IntegrationTransaction (interoperability_integrationtransaction),AuditLog (audit_auditlog)', 'processing': 'DB UID를 Orthanc QIDO-RS에 매핑하여 DICOM JSON metadata 반환. Pixel Data는 이 API가 반환하지 않고 WADO-RS URL을 사용', 'response_contract': 'DICOM JSON series metadata[], pagination; Orthanc 내부 ID와 환자 식별정보는 최소화', 'success': '200 OK', 'error_contract': '401 VIEWER_TOKEN_INVALID / 403 DICOM_SCOPE_FORBIDDEN / 404 STUDY_NOT_FOUND / 503 ORTHANC_UNAVAILABLE', 'transaction': 'X(조회 전용; VIEW_STUDY Audit/Integration은 별도 로깅 트랜잭션)', 'transactional': False, 'event': '-', 'note': '권한유형: SERVICE_SCOPE(dicomweb.read) / OHIF short-lived token', 'primary_model': 'imaging.SeriesReference', 'audit_required': True}])
