ContractView019 = build_contract_view([{'api_id': 'API-IMG-016', 'app': 'imaging', 'domain': 'Imaging/Internal', 'api_name': '영상검사 상태 이벤트 수신', 'method': 'POST', 'endpoint': '/internal/v1/imaging-orders/{order_id}/status-events', 'django_path': 'internal/v1/imaging-orders/<uuid:order_id>/status-events', 'roles': [], 'permission': None, 'service_scope': 'imaging.status.write', 'request_contract': 'Path: order_id; Body: status(SCHEDULED|IN_PROGRESS|HELD|COMPLETED|CANCELLED),occurred_at,reason,accession_number(optional),study_instance_uid(optional)', 'validation': 'Service 인증·멱등키; 최종 상태전이표; COMPLETED이면 Study UID/Order patient 일치. 담당장비·부서 컬럼은 최종 DB에 없어 저장하지 않음', 'related_db': 'ImagingOrder (imaging_imagingorder),ImagingOrderStatusHistory (imaging_imagingorderstatushistory),ImagingStudy (imaging_imagingstudy),IntegrationTransaction (interoperability_integrationtransaction),OutboxEvent (common_outboxevent)', 'processing': 'Order 상태와 History를 원자 반영하고 촬영완료 시 accession/Study 연결. 시스템 이벤트 recorded_by_id=NULL. Outbox 저장', 'response_contract': 'order_id,previous_status,status,occurred_at,study_id|null', 'success': '202 Accepted', 'error_contract': '400 INVALID_STATUS_EVENT / 404 ORDER_NOT_FOUND / 409 INVALID_STATUS_TRANSITION / 422 STUDY_ORDER_MISMATCH', 'transaction': 'O(필수: Order+History+Study link+IntegrationTransaction+Outbox 원자화)', 'transactional': True, 'event': 'imaging.order.status_changed.v1', 'note': '권한유형: SERVICE_SCOPE(imaging.status.write) / DB 미존재 장비·부서 필드 제외', 'primary_model': 'imaging.ImagingStudy', 'audit_required': False}])
